import { renderLoveOg } from "@/lib/love-og";
import { getCloudflareContext } from "@opennextjs/cloudflare";

const MEM = new Map<string, { at: number; buf: ArrayBuffer }>();
const MEM_TTL_MS = 12 * 60 * 60 * 1000;
const MEM_MAX = 150;

const CACHE_HEADER =
  "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800";
const FALLBACK_HEADER =
  "public, max-age=30, s-maxage=60, stale-while-revalidate=86400";

/** Instant crawler fallback — brand/og/love.png (no network) */
const STATIC_LOVE_OG_B64 =
  "";

function normRef(raw?: string | null): string {
  const h = (raw || "").replace(/^@/, "").trim().toLowerCase();
  if (!h || !/^[a-z0-9_]{1,15}$/.test(h)) return "";
  return h;
}

function memGet(key: string): ArrayBuffer | null {
  const hit = MEM.get(key);
  if (!hit) return null;
  if (Date.now() - hit.at > MEM_TTL_MS) {
    MEM.delete(key);
    return null;
  }
  return hit.buf;
}

function memSet(key: string, buf: ArrayBuffer) {
  if (MEM.size >= MEM_MAX) {
    const keys = [...MEM.entries()]
      .sort((a, b) => a[1].at - b[1].at)
      .slice(0, 40)
      .map(([k]) => k);
    for (const k of keys) MEM.delete(k);
  }
  MEM.set(key, { at: Date.now(), buf });
}

async function cfCacheMatch(req: Request): Promise<Response | null> {
  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const c = (globalThis as any).caches?.default as Cache | undefined;
    if (!c) return null;
    return (await c.match(req)) || null;
  } catch {
    return null;
  }
}

async function cfCachePut(req: Request, res: Response): Promise<void> {
  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const c = (globalThis as any).caches?.default as Cache | undefined;
    if (!c) return;
    await c.put(req, res.clone());
  } catch {
    /* */
  }
}

function pngResponse(
  buf: ArrayBuffer,
  via: string,
  header = CACHE_HEADER
): Response {
  return new Response(buf, {
    status: 200,
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": header,
      "X-Love-Og-Cache": via,
    },
  });
}

let staticFallback: ArrayBuffer | null = null;
function getStaticFallback(): ArrayBuffer {
  if (staticFallback && staticFallback.byteLength > 64) return staticFallback;
  const b = Buffer.from(STATIC_LOVE_OG_B64, "base64");
  staticFallback = b.buffer.slice(
    b.byteOffset,
    b.byteOffset + b.byteLength
  ) as ArrayBuffer;
  return staticFallback;
}

/** In-flight bakes so we don't stampede the same ref */
const baking = new Set<string>();

function scheduleBackground(task: Promise<unknown>) {
  try {
    const ctx = getCloudflareContext().ctx as {
      waitUntil?: (p: Promise<unknown>) => void;
    };
    if (typeof ctx?.waitUntil === "function") {
      ctx.waitUntil(task);
      return;
    }
  } catch {
    /* not on CF / no request context */
  }
  void task;
}

function bakeInBackground(ref: string, key: string, cacheReq: Request) {
  if (baking.has(key)) return;
  baking.add(key);
  scheduleBackground(
    (async () => {
      try {
        const img = await renderLoveOg(ref || null);
        const buf = await img.arrayBuffer();
        if (buf.byteLength > 64) {
          memSet(key, buf);
          await cfCachePut(cacheReq, pngResponse(buf, "bg"));
        }
      } catch (e) {
        console.error("love-og bake", ref, e);
      } finally {
        baking.delete(key);
      }
    })()
  );
}

/**
 * Love OG — never block HTTP on Satori (blocks event loop / crawler timeouts).
 * Cached → personalized PNG. Miss → static brand OG instantly + bg bake.
 */
export async function getLoveOgPngResponse(
  rawRef?: string | null,
  requestUrl?: string
): Promise<Response> {
  const ref = normRef(rawRef);
  const key = `love-og:v5:${ref || "_"}`;
  const cacheUrl =
    requestUrl?.split("&v=")[0] ||
    `https://tokenshit.com/api/love/og?ref=${encodeURIComponent(ref)}&k=${key}`;
  const cacheReq = new Request(cacheUrl, { method: "GET" });

  const mem = memGet(key);
  if (mem) return pngResponse(mem, "memory");

  try {
    const cached = await cfCacheMatch(cacheReq);
    if (cached && cached.ok) {
      const buf = await cached.arrayBuffer();
      if (buf.byteLength > 64) {
        memSet(key, buf);
        return pngResponse(buf, "cf");
      }
    }
  } catch {
    /* */
  }

  // MISS — respond with static instantly; personalize in background
  bakeInBackground(ref, key, cacheReq);
  return pngResponse(getStaticFallback(), "fallback-static", FALLBACK_HEADER);
}

/** Await full bake (for SSR prewarm only — not crawler path). */
export async function prewarmLoveOg(rawRef?: string | null): Promise<boolean> {
  const ref = normRef(rawRef);
  const key = `love-og:v5:${ref || "_"}`;
  if (memGet(key)) return true;
  try {
    const img = await renderLoveOg(ref || null);
    const buf = await img.arrayBuffer();
    if (buf.byteLength < 64) return false;
    memSet(key, buf);
    const cacheUrl = `https://tokenshit.com/api/love/og?ref=${encodeURIComponent(ref)}&k=${key}`;
    void cfCachePut(new Request(cacheUrl), pngResponse(buf, "prewarm"));
    return true;
  } catch {
    return false;
  }
}
